<script setup lang="ts">
import type { RepairCard } from '../types/repairWork'
import {reviewChecks} from '../types/repairWork'
defineProps<{card:RepairCard}>()
const time=(iso:string)=>new Date(iso).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'})
</script>
<template>
 <article class="repair-readout" :data-card-id="card.id"><div class="repair-readout-meta"><span class="record-code">KARTU {{ card.id.slice(-8).toUpperCase() }}</span><span class="finding-status" :class="!card.review?'awaiting_review':card.review.result==='accepted'?'closed':'rework'">{{ !card.review?'Menunggu pemeriksaan':card.review.result==='accepted'?'Hasil diterima':'Pengerjaan ulang' }}</span></div><dl class="repair-fields"><div><dt>Teknisi</dt><dd>{{ card.technician }}</dd></div><div><dt>Mulai</dt><dd>{{ time(card.startedAt) }} WIB</dd></div><div><dt>Selesai</dt><dd>{{ time(card.completedAt) }} WIB</dd></div><div><dt>Durasi tercatat</dt><dd>{{ Math.round((Date.parse(card.completedAt)-Date.parse(card.startedAt))/60000) }} menit</dd></div></dl><h4>Tindakan pengerjaan</h4><p class="repair-text">{{ card.actions }}</p><h4>Dokumen rujukan</h4><p class="repair-text">{{ card.reference }}</p><div class="repair-evidence"><section><h4>Sebelum</h4><div class="repair-evidence-photos"><figure v-for="photo in card.beforePhotos" :key="photo.id"><FindingPhoto :photo="photo" /><figcaption>{{ photo.name }}</figcaption></figure></div></section><section><h4>Sesudah</h4><div class="repair-evidence-photos"><figure v-for="photo in card.afterPhotos" :key="photo.id"><FindingPhoto :photo="photo" /><figcaption>{{ photo.name }}</figcaption></figure></div></section></div><h4>Material saat kartu diajukan</h4><p v-if="!card.materials.length" class="field-help">Tidak ada material diserahkan yang dicatat untuk kartu ini.</p><ul v-else class="repair-material-snapshot"><li v-for="material in card.materials" :key="material.requestId"><strong>{{ material.name }} · {{ material.partNumber }}</strong><p>Diserahkan {{ material.issued }} · Dipakai {{ material.used }} · Dikembalikan {{ material.returned }} {{ material.unit }}</p><small v-for="entry in material.dispositions" :key="entry.id">{{ entry.kind==='used'?'Dipakai':'Dikembalikan' }} {{ entry.quantity }} · {{ entry.actor }}<template v-if="entry.serialLot"> · Seri/lot {{ entry.serialLot }}</template> · {{ entry.note }}</small></li></ul><section v-if="card.review" class="repair-review-result"><h4>{{ card.review.result==='accepted'?'Pemeriksaan demo diterima':'Diminta pengerjaan ulang' }}</h4><p>{{ card.review.inspector }} · {{ time(card.review.at) }} WIB</p><p class="repair-text">{{ card.review.note }}</p><ul><li v-for="check in card.review.checks" :key="check">{{ reviewChecks[check] }}</li></ul></section></article>
</template>
